changeSet.sql:
CREATE TABLE messages ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, chat_id UUID NOT NULL, sender_profile_id BIGINT NOT NULL, -- Nessuna FK verso profiles: integrità garantita a livello applicativo. text TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ, deleted_at TIMESTAMPTZ,
CONSTRAINT MESSAGES_CHAT_FK FOREIGN KEY (chat_id) REFERENCES chats(id) ON DELETE CASCADE -- La FK verso chats è interna a directs-service → rimane. );
CREATE INDEX idx_messages_chat ON messages(chat_id, created_at DESC) WHERE deleted_at IS NULL; CREATE INDEX idx_messages_sender ON messages(sender_profile_id) WHERE deleted_at IS NULL;
